import test from 'node:test';import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {MockAdapter,RoleProviderRouter} from '@orchestrator/adapters';
import {DEFAULT_PROVIDER_CONFIG,PROVIDER_REGISTRY,SSE_EVENT_TYPES,makeSseEnvelope,providerAuthSemantics} from '@orchestrator/shared';
import {BudgetExceededError,BudgetGuard,ExecutionWatchdog,WorkspaceLockManager,assertPipelineApprovalIntegrity,resumeIndex,PipelineRunner} from '@orchestrator/core';
