test('provider capabilities are explicit and mock reports usage',async()=>{const a=new MockAdapter();assert.equal(await a.checkAvailability(),true);assert.equal(a.capabilities.cancel,true);assert.equal(a.capabilities.filesystemAccess,false);const result=await a.execute({stage:'reviewer'});assert.match(result.output,/APPROVED/);assert.equal(result.stdout,result.output);assert.equal(result.stderr,'');assert.equal(result.progressEvents.length,3);assert.equal(result.structuredResult?.status,'APPROVED');assert.equal(result.providerSessionId,'mock-session');assert.equal(result.conversationId,'mock-conversation');assert.equal(result.resumeToken,'mock-resume-token');assert.ok(result.tokenUsage>0);});
test('budget guard blocks exceeded spend',()=>{const guard=new BudgetGuard(1,100);assert.throws(()=>guard.assertCanStart(1.1,0),BudgetExceededError);assert.throws(()=>guard.assertCanStart(0,101),BudgetExceededError);});
test('workspace lock prevents concurrent ownership',()=>{const locks=new WorkspaceLockManager();locks.acquire('workspace:w','a');assert.throws(()=>locks.acquire('workspace:w','b'),/Lock busy/);locks.release('workspace:w','a');locks.acquire('workspace:w','b');});
test('resume starts after last successful stage',()=>{assert.equal(resumeIndex(['planner','developer','tester','reviewer'],'developer'),2);assert.equal(resumeIndex(['planner','developer'],undefined),0);});
test('watchdog marks stalled execution after missing heartbeat',async()=>{await new Promise<void>((resolve,reject)=>{const watchdog=new ExecutionWatchdog(250,()=>{watchdog.stop();resolve();});watchdog.start();setTimeout(()=>{watchdog.stop();reject(new Error('watchdog did not fire'));},700);});});
test('pipeline cancellation propagates',async()=>{const controller=new AbortController();controller.abort();const runner=new PipelineRunner(new MockAdapter(),{onStageStart(){},onStageComplete(){},onProgress(){},onHeartbeat(){},onFailure(){}});await assert.rejects(runner.run({task:{} as any,workspaceContext:{} as any,projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:0,budgetUsd:0}},['planner'],0,controller.signal),/cancelled/i);});
test('reviewer approval integrity requires reviewer completion and last safe stage',async()=>{const roles:string[]=[];const adapter:any={execute:async(input:any)=>{roles.push(input.stage);return{output:input.stage,tokenUsage:0,structuredResult:input.stage==='reviewer'?{status:'APPROVED'}:{status:'COMPLETED'}};}};const runner=new PipelineRunner(adapter,{onStageStart(){},onStageComplete(){},onProgress(){},onHeartbeat(){},onFailure(){}});await runner.run({task:{configSnapshot:{autoFixEnabled:false}} as any,workspaceContext:{} as any,projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:0,budgetUsd:0}},['planner','developer','tester','reviewer']);assert.deepEqual(roles,['planner','developer','tester','reviewer']);assert.doesNotThrow(()=>assertPipelineApprovalIntegrity({pipeline:['planner','developer','tester','reviewer'],lastSuccessfulStage:'reviewer'},roles.map(role=>({role,status:'completed',structuredResult:role==='reviewer'?{status:'APPROVED'}:{status:'COMPLETED'}}))));assert.throws(()=>assertPipelineApprovalIntegrity({pipeline:['planner','developer','tester','reviewer'],lastSuccessfulStage:'tester'},roles.slice(0,3).map(role=>({role,status:'completed',structuredResult:{status:'COMPLETED'}}))),error=>{assert.equal((error as any).kind,'pipeline_incomplete');assert.deepEqual((error as any).details.missingStages,['reviewer']);return true;});});
test('tester cannot silently finish a pipeline that requires reviewer',async()=>{const runner=new PipelineRunner({execute:async(input:any)=>({output:input.stage,tokenUsage:0,structuredResult:input.stage==='tester'?{status:'FAILED'}:{status:'COMPLETED'}})} as any,{onStageStart(){},onStageComplete(){},onProgress(){},onHeartbeat(){},onFailure(){}});await assert.rejects(runner.run({task:{configSnapshot:{autoFixEnabled:false}} as any,workspaceContext:{} as any,projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:0,budgetUsd:0}},['planner','developer','tester','reviewer']),error=>{assert.equal((error as any).kind,'pipeline_incomplete');return true;});});

test('pipeline retries provider errors according to policy',async()=>{let calls=0;const adapter:any={execute:async()=>{calls++;if(calls===1)throw Object.assign(new Error('temporary'),{kind:'provider_error'});return{output:'ok',tokenUsage:1,estimatedCost:0};}};const runner=new PipelineRunner(adapter,{onStageStart(){},onStageComplete(){},onProgress(){},onHeartbeat(){},onFailure(){}});const output=await runner.run({task:{} as any,workspaceContext:{} as any,projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:0,budgetUsd:0}},['planner']);assert.equal(output[0],'ok');assert.equal(calls,2);});

import {EventEmitter} from 'node:events';
import {CodexCliAdapter,ReviewerProviderRouter,resolveExecutable} from '@orchestrator/adapters';

const codexContext:any={task:{id:'codex-test',title:'Review',description:'Review safely',pipeline:['reviewer'],status:'reviewing',resumable:true,workspaceId:'w',taskBudgetUsd:1,tokenBudget:1000,configSnapshot:'{}',createdAt:'',updatedAt:''},workspaceContext:{id:'w',type:'local',location:process.cwd(),branch:'main'},projectRules:[],stage:'reviewer',previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:1000,budgetUsd:1}};
function fakeSpawn(config:{stdout?:string;stderr?:string;code?:number|null;delay?:number;never?:boolean;onChildCreated?:(child:any)=>void;synchronousMetadata?:boolean}={}){return (_command:string,args:string[])=>{const child:any=new EventEmitter();child.stdout=new EventEmitter();child.stderr=new EventEmitter();const metadata=args.includes('--help')||args.includes('--version');child.stdin={end(){if(config.never&&!metadata)return;const finish=()=>{const output=args.includes('--help')?'Usage: codex exec [OPTIONS] [PROMPT]\n      --json\n      --sandbox <MODE>\n      --model <MODEL>':args.includes('--version')?(config.stdout||'codex-cli 0.160.0'):config.stdout;if(output)child.stdout.emit('data',Buffer.from(output));if(config.stderr)child.stderr.emit('data',Buffer.from(config.stderr));child.emit('close',metadata?0:(config.code??0));};if(metadata)finish();else setTimeout(finish,config.delay||0);}};child.kill=()=>{if(!child.closed){child.closed=true;child.emit('close',null);}};child.args=args;config.onChildCreated?.(child);return child;};}
function review(status:'APPROVED'|'NEEDS_FIX'='APPROVED'){return JSON.stringify({status,summary:'review summary',issues:status==='APPROVED'?[]:[{severity:'high',file:'src/app.ts',description:'Fix this issue'}]});}

test('codex reports CLI missing separately from authentication',async()=>{const adapter=new CodexCliAdapter({executable:'codex-not-installed-for-test'});assert.equal(await adapter.checkAvailability(),false);const health=await adapter.getHealth();assert.equal(health.available,false);assert.equal(health.authenticated,false);});
test('codex health captures version and authentication error',async()=>{const adapter=new CodexCliAdapter({executable:'codex',spawn:fakeSpawn({stdout:'codex 1.2.3',stderr:'authentication required',code:0})});assert.equal(await adapter.checkAvailability(),true);const health=await adapter.getHealth();assert.equal(health.version,'1.2.3');assert.equal(health.authenticated,false);assert.equal(health.authenticationStatus,'unknown');});
test('codex rejects non-zero exit and captures stderr',async()=>{const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stderr:'cli failure',code:2})});await assert.rejects(adapter.execute(codexContext),error=>{assert.equal((error as any).kind,'provider_error');assert.match(String(error),/cli failure/);return true;});});
test('codex validates APPROVED JSON and structured output',async()=>{let args:string[]=[];const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:(command,a)=>{args=a;return fakeSpawn({stdout:review('APPROVED')})(command,a);}});const result=await adapter.execute({...codexContext,onProgress(){},onHeartbeat(){}});assert.equal(result.structuredResult?.status,'APPROVED');assert.equal(result.stderr,'');assert.equal(result.tokenUsage,0);assert.ok(args.includes('--sandbox'));});
test('codex validates NEEDS_FIX JSON without textual approval fallback',async()=>{const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:review('NEEDS_FIX')})});const result=await adapter.execute(codexContext);assert.equal(result.structuredResult?.status,'NEEDS_FIX');assert.match(result.output,/NEEDS_FIX/);});
test('codex parses JSONL and uses the last valid agent_message',async()=>{const stream=[JSON.stringify({type:'thread.started',thread_id:'abc'}),'{not-json}',JSON.stringify({type:'item.completed',item:{type:'agent_message',text:'Analisando projeto...'}}),JSON.stringify({type:'item.completed',item:{type:'agent_message',text:review('APPROVED')}}),JSON.stringify({type:'turn.completed',usage:{input_tokens:100,output_tokens:20}})].join('\n');const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:stream})});const result=await adapter.execute(codexContext);assert.equal(result.structuredResult?.status,'APPROVED');assert.equal((result.rawProviderResponse as any).events.length,4);assert.equal((result.rawProviderResponse as any).turnCompleted,true);assert.equal(result.tokenUsage,120);});
test('codex parses NEEDS_FIX JSON inside a markdown code fence',async()=>{const text='```json\n'+review('NEEDS_FIX')+'\n```';const stream=JSON.stringify({type:'item.completed',item:{type:'agent_message',text}})+'\n'+JSON.stringify({type:'turn.completed'});const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:stream})});const result=await adapter.execute(codexContext);assert.equal(result.structuredResult?.status,'NEEDS_FIX');});
test('codex reports provider error when stream fails without completed turn',async()=>{const stream=JSON.stringify({type:'error',message:'provider failed'});const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:stream})});await assert.rejects(adapter.execute(codexContext),error=>{assert.equal((error as any).kind,'provider_error');return true;});});
test('codex rejects invalid JSON even when stdout contains APPROVED text',async()=>{const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:fakeSpawn({stdout:'APPROVED but not JSON'})});await assert.rejects(adapter.execute(codexContext),error=>{assert.equal((error as any).kind,'validation_error');return true;});});
test('codex times out and terminates only its child',async()=>{const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',timeoutMs:20,spawn:fakeSpawn({never:true})});await assert.rejects(adapter.execute(codexContext),error=>{assert.equal((error as any).kind,'timeout');return true;});});
test('codex responds to AbortSignal and cancel',async()=>{const controller=new AbortController();const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',timeoutMs:1000,spawn:fakeSpawn({never:true})});const promise=adapter.execute({...codexContext,signal:controller.signal});controller.abort();await assert.rejects(promise,error=>{assert.equal((error as any).kind,'cancelled');return true;});});
test('codex blocks invalid budget before spawning',async()=>{let spawned=false;const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',spawn:(command,args)=>{spawned=true;return fakeSpawn({stdout:review()})(command,args);}});await assert.rejects(adapter.execute({...codexContext,constraints:{timeoutSeconds:1,tokenBudget:1000,budgetUsd:-1}}),error=>{assert.equal((error as any).kind,'budget_exceeded');return true;});assert.equal(spawned,false);});
test('codex exposes the explicitly configured environment model',async()=>{assert.deepEqual(await new CodexCliAdapter({env:{...process.env,CODEX_MODEL:'gpt-5.6-luna'}}).getModels(),['gpt-5.6-luna']);});
test('codex exposes no model when CODEX_MODEL is not configured',async()=>{const env={...process.env};delete env.CODEX_MODEL;assert.deepEqual(await new CodexCliAdapter({env}).getModels(),[]);});
test('codex never invents a hardcoded model catalog',async()=>{const env={...process.env};delete env.CODEX_MODEL;const adapter=new CodexCliAdapter({env});assert.deepEqual(await adapter.getModels(),[]);assert.deepEqual(await new CodexCliAdapter({model:'configured-model',env}).getModels(),['configured-model']);});


