test('health check keeps authentication unknown after safe version check',async()=>{const adapter=new CodexCliAdapter({executable:'codex.cmd',platform:'win32',spawn:fakeSpawn({stdout:'codex-cli 0.160.0'})});assert.equal(await adapter.checkAvailability(),true);const health=await adapter.getHealth();assert.equal(health.available,true);assert.equal(health.version,'0.160.0');assert.equal(health.authenticationStatus,'unknown');assert.equal(health.resolvedExecutable,'codex.cmd');});

