test('watchdog heartbeat prevents stalled while activity continues',async()=>{let stalled=0;const watchdog=new ExecutionWatchdog(80,()=>{stalled++;});watchdog.start();for(let i=0;i<4;i++){await new Promise(r=>setTimeout(r,35));watchdog.beat();}watchdog.stop();assert.equal(stalled,0);});


