test('codex 0.160 capability check detects json sandbox and model without prompt',async()=>{let promptCalls=0;const adapter=new CodexCliAdapter({executable:'codex',model:'gpt-5.6-luna',spawn:(command,args,options)=>{if(!args.includes('--help')&&!args.includes('--version'))promptCalls++;return fakeSpawn()(command,args);}});assert.equal(await adapter.checkAvailability(),true);const health=await adapter.getHealth();assert.deepEqual(health.supportedExecFlags,['--json','--sandbox','--model']);assert.deepEqual(health.unsupportedConfiguredFlags,[]);assert.equal(promptCalls,0);});
test('unsupported ask-for-approval is configuration_error before prompt',async()=>{let promptCalls=0;const adapter=new CodexCliAdapter({executable:'codex',model:'gpt-5.6-luna',safeArgs:['exec','--json','--sandbox','read-only','--ask-for-approval','never'],spawn:(command,args,options)=>{if(!args.includes('--help')&&!args.includes('--version'))promptCalls++;return fakeSpawn()(command,args);}});await assert.rejects(adapter.execute(codexContext),error=>{assert.equal((error as any).kind,'configuration_error');assert.match(String(error),/Unsupported Codex CLI argument: --ask-for-approval/);return true;});assert.equal(promptCalls,0);const health=await adapter.getHealth();assert.deepEqual(health.unsupportedConfiguredFlags,['--ask-for-approval']);});
