test('silent Codex process emits heartbeat without fake progress and stops after cancel',async()=>{const controller=new AbortController();let heartbeats=0;let progress=0;let tick:(()=>void)|undefined;let cleared=false;const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',heartbeatIntervalMs:20,timeoutMs:500,spawn:fakeSpawn({never:true}),setIntervalFn:handler=>{tick=handler;return {} as ReturnType<typeof setInterval>},clearIntervalFn:()=>{cleared=true}});const promise=adapter.execute({...codexContext,signal:controller.signal,onHeartbeat:()=>heartbeats++,onProgress:()=>progress++});await new Promise<void>(resolve=>setImmediate(resolve));assert.ok(tick);tick!();assert.equal(heartbeats,1);tick!();assert.equal(heartbeats,2);assert.equal(progress,0);controller.abort();await assert.rejects(promise,error=>{assert.equal((error as any).kind,'cancelled');return true;});assert.equal(cleared,true);tick!();assert.equal(heartbeats,2);});
test('silent Codex process heartbeat stops after process close',async()=>{let heartbeats=0;let tick:(()=>void)|undefined;let child:any;const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',timeoutMs:500,spawn:fakeSpawn({never:true,onChildCreated:(created:any)=>{child=created}} as any),setIntervalFn:handler=>{tick=handler;return {} as ReturnType<typeof setInterval>},clearIntervalFn:()=>{}});const promise=adapter.execute({...codexContext,onHeartbeat:()=>heartbeats++});await new Promise<void>(resolve=>setImmediate(resolve));assert.ok(tick);tick!();assert.equal(heartbeats,1);child.emit('close',2);await assert.rejects(promise);tick!();assert.equal(heartbeats,1);});
test('Codex total timeout is distinct from provider stall heartbeat',async()=>{let heartbeats=0;let tick:(()=>void)|undefined;let cleared=false;const adapter=new CodexCliAdapter({executable:'codex',model:'configured-model',heartbeatIntervalMs:15,timeoutMs:70,spawn:fakeSpawn({never:true}),setIntervalFn:handler=>{tick=handler;return {} as ReturnType<typeof setInterval>},clearIntervalFn:()=>{cleared=true}});const promise=adapter.execute({...codexContext,onHeartbeat:()=>heartbeats++});await new Promise<void>(resolve=>setImmediate(resolve));assert.ok(tick);tick!();assert.equal(heartbeats,1);await assert.rejects(promise,error=>{assert.equal((error as any).kind,'timeout');return true;});assert.equal(cleared,true);tick!();assert.equal(heartbeats,1);});


test('stalled reviewer resume starts a new reviewer execution without rerunning safe stages',async()=>{const started:string[]=[];const runner=new PipelineRunner(new MockAdapter(),{onStageStart:role=>{started.push(role)},onStageComplete(){},onProgress(){},onHeartbeat(){},onFailure(){}});await runner.run({task:{} as any,workspaceContext:{} as any,projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:5,tokenBudget:0,budgetUsd:0}},['planner','developer','tester','reviewer'],resumeIndex(['planner','developer','tester','reviewer'],'tester'));assert.deepEqual(started,['reviewer']);assert.equal(resumeIndex(['planner','developer','tester','reviewer'],'tester'),3);});


test('NEEDS_FIX reviewer result completes once and does not retry',async()=>{let calls=0;let completed:any;const adapter:any={execute:async()=>{calls++;return{output:'review',tokenUsage:4,estimatedCost:0,structuredResult:{status:'NEEDS_FIX',summary:'issues',issues:[{severity:'high',file:'index.html',description:'encoding'}]}};}};const runner=new PipelineRunner(adapter,{onStageStart(){},onStageComplete:(_role,result)=>{completed=result;},onProgress(){},onHeartbeat(){},onFailure(){}});await runner.run({task:{} as any,workspaceContext:{} as any,projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:0,budgetUsd:0}},['reviewer']);assert.equal(calls,1);assert.equal(completed.structuredResult.status,'NEEDS_FIX');});
test('bounded auto-fix loop runs developer/tester/reviewer without rerunning planner',async()=>{const roles:string[]=[];let reviewCount=0;let fixerPrompt='';const adapter:any={execute:async(input:any)=>{roles.push(input.stage);if(input.stage==='developer')fixerPrompt=input.stageContext.prompt;if(input.stage==='reviewer'){reviewCount++;return{output:'review',tokenUsage:1,estimatedCost:0,structuredResult:reviewCount===1?{status:'NEEDS_FIX',summary:'fix',issues:[{severity:'high',file:'a.ts',description:'issue X'}]}:{status:'APPROVED',summary:'ok',issues:[]}};}return{output:input.stage,tokenUsage:1,estimatedCost:0,structuredResult:{status:'COMPLETED'}};}};const runner=new PipelineRunner(adapter,{onStageStart(){},onStageComplete(){},onProgress(){},onHeartbeat(){},onFailure(){}});const base:any={task:{id:'fix-task',title:'Fix',description:'task',configSnapshot:{autoFixEnabled:true,maxFixCycles:2}},workspaceContext:{id:'w',type:'local',location:process.cwd()},projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:0,budgetUsd:0}};await runner.run(base,['planner','developer','tester','reviewer']);assert.deepEqual(roles,['planner','developer','tester','reviewer','developer','tester','reviewer']);assert.match(fixerPrompt,/issue X/);});
test('auto-fix disabled stops at NEEDS_FIX',async()=>{let developers=0;let reviews=0;const adapter:any={execute:async(input:any)=>{if(input.stage==='developer')developers++;if(input.stage==='reviewer')reviews++;return{output:'x',tokenUsage:0,structuredResult:input.stage==='reviewer'?{status:'NEEDS_FIX',issues:[]}:{status:'COMPLETED'}};}};const runner=new PipelineRunner(adapter,{onStageStart(){},onStageComplete(){},onProgress(){},onHeartbeat(){},onFailure(){}});const base:any={task:{id:'off-task',title:'Fix',description:'task',configSnapshot:{autoFixEnabled:false,maxFixCycles:2}},workspaceContext:{id:'w',type:'local',location:process.cwd()},projectRules:[],previousArtifacts:[],constraints:{timeoutSeconds:1,tokenBudget:0,budgetUsd:0}};await runner.run(base,['developer','reviewer']);assert.equal(developers,1);assert.equal(reviews,1);});

import {ClaudeCodeAdapter,buildClaudeArgs,parseClaudeCapabilities,resolveClaudeExecutable,buildWindowsCmdInvocation} from '@orchestrator/adapters';
function fakeClaudeSpawn(config:{stdout?:string;stderr?:string;code?:number|null;delay?:number;never?:boolean;onStdin?:(value:string)=>void}={}){return (_command:string,args:string[],_options?:any)=>{const child:any=new EventEmitter();child.stdout=new EventEmitter();child.stderr=new EventEmitter();const metadata=args.includes('--version')||args.includes('--help');child.stdin={end(value?:string){config.onStdin?.(value||'');if(config.never&&!metadata)return;setTimeout(()=>{const output=args.includes('--version')?'Claude Code 1.2.3':args.includes('--help')?'Claude Code - starts an interactive session by default, use -p/--print for non-interactive output\\nUsage: claude [OPTIONS]\n  -p, --print\n  --model <model>\n  --allowedTools <tools...>\n  --disallowedTools <tools...>\n  --permission-mode <mode> (default acceptEdits dontAsk)\n  --max-turns <n>\n  --output-format <format>':config.stdout;if(output)child.stdout.emit('data',Buffer.from(output));if(config.stderr)child.stderr.emit('data',Buffer.from(config.stderr));child.emit('close',metadata?0:(config.code??0));},config.delay||0);}};child.kill=()=>{if(!child.closed){child.closed=true;child.emit('close',null);}};return child;};}
const claudeContext:any={task:{id:'claude-test',title:'Implement feature',description:'Implement safely',pipeline:['planner','developer','tester','reviewer'],status:'implementing',resumable:true,workspaceId:'w',taskBudgetUsd:1,tokenBudget:1000,configSnapshot:'{}',createdAt:'',updatedAt:''},workspaceContext:{id:'w',type:'local',location:'/tmp/workspace',branch:'main'},projectRules:[],stage:'developer',previousArtifacts:[],constraints:{timeoutSeconds:10,tokenBudget:1000,budgetUsd:1}};
const developerResult=JSON.stringify({status:'COMPLETED',summary:'Implemented safely',filesChanged:['src/app.ts'],testsRun:[{command:'pnpm test',status:'passed'}],notes:[]});
test('Claude args preserve tool patterns as individual arguments and cmd invocation is shell-free',()=>{const args=buildClaudeArgs({model:'sonnet',supportedFlags:['-p','--model','--allowedTools','--disallowedTools','--max-turns'],allowedTools:['Bash(git status:*)','Bash(php -l:*)'],disallowedTools:['Bash(git commit:*)'],maxTurns:15,safeArgs:[]});assert.ok(args.some(arg=>arg.includes('Bash(php -l:*)')));assert.ok(!args.includes('-l:*)'));const wrapped=buildWindowsCmdInvocation({executable:'C:\\Program Files\\Claude\\claude.cmd',args});assert.equal(wrapped.command,'cmd.exe');assert.equal(wrapped.shell,false);});
test('claude resolver honors configured path and Windows npm wrappers',()=>{assert.equal(resolveClaudeExecutable({explicit:'C:/Tools/Claude Code/claude.cmd',platform:'win32'})?.isWindowsWrapper,true);assert.equal(resolveClaudeExecutable({platform:'win32',env:{PATH:'C:/bin',APPDATA:'C:/Users/test/AppData/Roaming'},pathExists:path=>path.includes('AppData\\Roaming\\npm')&&path.endsWith('claude.cmd')})?.path,'C:\\Users\\test\\AppData\\Roaming\\npm\\claude.cmd');});
test('claude health uses version/help without model execution',async()=>{const adapter=new ClaudeCodeAdapter({executable:'claude',spawn:fakeClaudeSpawn()});assert.equal(await adapter.checkAvailability(),true);const health=await adapter.getHealth();assert.equal(health.version,'Claude Code 1.2.3');assert.deepEqual(health.supportedCliFlags,['-p','--print','--model','--output-format','--allowedTools','--disallowedTools','--permission-mode','--max-turns']);assert.equal(health.authenticationStatus,'unknown');});
test('claude validates developer structured result and workspace cwd',async()=>{let cwd='';let args:string[]=[];const adapter=new ClaudeCodeAdapter({executable:'claude',model:'sonnet-test',spawn:(command,a,options)=>{cwd=options.cwd||'';args=a;return fakeClaudeSpawn({stdout:developerResult})(command,a,options);}});const result=await adapter.execute(claudeContext);assert.equal(result.structuredResult?.status,'COMPLETED');assert.equal(cwd,'/tmp/workspace');assert.ok(args.includes('-p'));assert.ok(args.includes('--model'));});test('claude sends shell-sensitive prompt through stdin and never puts it in args',async()=>{let stdin='';let args:string[]=[];const task={...claudeContext,task:{...claudeContext.task,title:'Return ONLY: {\"status\":\"COMPLETED\"|\"BLOCKED\"}',description:'Teste A | Teste B; a & b; x > y; \"quoted\"; {json} [] ()'}};const adapter=new ClaudeCodeAdapter({executable:'C:/Users/test/AppData/Roaming/npm/claude.cmd',platform:'win32',model:'sonnet-test',spawn:(command,a)=>{args=a;return fakeClaudeSpawn({stdout:developerResult,onStdin:value=>{stdin=value}})(command,a);}});const result=await adapter.execute(task);assert.equal(result.structuredResult?.status,'COMPLETED');assert.ok(stdin.includes('Teste A | Teste B'));assert.ok(stdin.includes('a & b'));assert.ok(stdin.includes('x > y'));assert.ok(stdin.includes('\"quoted\"'));assert.ok(!args.some(arg=>arg.includes('|')||arg.includes('&')||arg.includes('Teste A')));assert.ok(args.includes('-p'));assert.ok(args.includes('--model'));assert.ok(args.includes('--allowedTools'));assert.ok(args.includes('--disallowedTools'));assert.ok(args.some(arg=>arg.includes('Read')&&arg.includes('Write')));assert.ok(args.some(arg=>arg.includes('Bash(git commit:*)')));assert.ok(args.includes('--permission-mode'));assert.ok(args.includes('dontAsk'));assert.ok(args.includes('--max-turns'));assert.ok(args.includes('15'));assert.ok(!args.includes('--dangerously-skip-permissions'));});
test('claude rejects other roles and missing model',async()=>{const adapter=new ClaudeCodeAdapter({executable:'claude',spawn:fakeClaudeSpawn()});await assert.rejects(adapter.execute({...claudeContext,stage:'reviewer'}),error=>{assert.equal((error as any).kind,'validation_error');return true;});await assert.rejects(adapter.execute(claudeContext),error=>{assert.equal((error as any).kind,'validation_error');return true;});});
test('claude rejects unsupported configured safe args before execution',async()=>{const adapter=new ClaudeCodeAdapter({executable:'claude',model:'sonnet-test',safeArgs:['--unsafe-flag'],spawn:fakeClaudeSpawn()});await assert.rejects(adapter.execute(claudeContext),error=>{assert.equal((error as any).kind,'configuration_error');return true;});});
test('claude emits heartbeat, supports abort and timeout',async()=>{let heartbeats=0;const adapter=new ClaudeCodeAdapter({executable:'claude',model:'sonnet-test',heartbeatIntervalMs:10,timeoutMs:35,spawn:fakeClaudeSpawn({never:true})});await assert.rejects(adapter.execute({...claudeContext,onHeartbeat:()=>heartbeats++}),error=>{assert.equal((error as any).kind,'timeout');return true;});assert.ok(heartbeats>=1);const controller=new AbortController();const cancellable=new ClaudeCodeAdapter({executable:'claude',model:'sonnet-test',spawn:fakeClaudeSpawn({never:true})});const promise=cancellable.execute({...claudeContext,signal:controller.signal});setTimeout(()=>controller.abort(),5);await assert.rejects(promise,error=>{assert.equal((error as any).kind,'cancelled');return true;});});
