test('task config UI clarifies tester blocked policy without renaming snapshot field',()=>{const source=readFileSync(new URL('../../web/src/main.tsx',import.meta.url),'utf8');assert.match(source,/Bloquear se testes não puderem ser executados/);assert.match(source,/Quando ativo, resultado BLOCKED do Tester exige intervenção\./);assert.match(source,/task\.configSnapshot\?\.testerRequired\?'Sim':'Não'/);assert.doesNotMatch(source,/Tester obrigatório/);});
test('providers UI keeps save feedback and dirty-state guards',()=>{const source=readFileSync(new URL('../../web/src/ProvidersPage.tsx',import.meta.url),'utf8');assert.match(source,/!dirty\|\|Boolean\(invalid\)\|\|saving/);assert.match(source,/Configuração salva com sucesso\./);assert.match(source,/Não foi possível salvar a configuração\./);assert.match(source,/const dirty=!equal\(savedConfig,draftConfig\)/);assert.match(source,/response\?\.global\|\|draftConfig/);});
test('workspace detail keeps provider settings responsive and semantically isolated',()=>{const main=readFileSync(new URL('../../web/src/main.tsx',import.meta.url),'utf8');const agents=readFileSync(new URL('../../web/src/WorkspaceAgentConfig.tsx',import.meta.url),'utf8');const providers=readFileSync(new URL('../../web/src/ProvidersPage.tsx',import.meta.url),'utf8');const css=readFileSync(new URL('../../web/src/composition-final.css',import.meta.url),'utf8');assert.match(main,/WorkspaceAgentConfig workspace=\{workspace\} notify=\{notify\}/);assert.match(agents,/Usando configuração global/);assert.match(agents,/Configuração personalizada/);assert.match(agents,/const dirty=Boolean\(draftConfig\)&&!equal\(savedConfig,draftConfig\)/);assert.match(agents,/Configuração do workspace salva\./);assert.match(agents,/Não foi possível salvar a configuração do workspace\./);assert.match(agents,/Usar configuração global/);assert.match(agents,/workspace-provider-role/);assert.match(css,/grid-template-columns:minmax\(0,1fr\) minmax\(0,380px\)/);assert.match(css,/@media\(max-width:1279px\)/);assert.match(css,/workspace-rail select/);assert.doesNotMatch(css,/body[^}]*overflow-x:hidden/);assert.match(providers,/Atualizando\.\.\./);assert.match(providers,/Status dos providers atualizado\./);assert.match(providers,/Não foi possível atualizar o status dos providers\./);});
test('provider auth semantics normalize stale health values at the source',()=>{assert.deepEqual(providerAuthSemantics('claude-code'),{authMode:'cli_managed',authenticationStatus:'cli_managed'});assert.deepEqual(providerAuthSemantics('codex-cli'),{authMode:'cli_managed',authenticationStatus:'cli_managed'});assert.deepEqual(providerAuthSemantics('command-tester'),{authMode:'not_applicable',authenticationStatus:'not_applicable'});assert.deepEqual(providerAuthSemantics('mock'),{authMode:'not_applicable',authenticationStatus:'not_applicable'});const stale={claude:{authenticationStatus:'not_configured'},codex:{authenticationStatus:'not_configured'},tester:{authenticationStatus:'authenticated'},mock:{authenticationStatus:'authenticated'}};const normalized={claude:{...stale.claude,...providerAuthSemantics('claude-code')},codex:{...stale.codex,...providerAuthSemantics('codex-cli')},tester:{...stale.tester,...providerAuthSemantics('command-tester')},mock:{...stale.mock,...providerAuthSemantics('mock')}};assert.deepEqual(normalized,{claude:{authenticationStatus:'cli_managed',authMode:'cli_managed'},codex:{authenticationStatus:'cli_managed',authMode:'cli_managed'},tester:{authenticationStatus:'not_applicable',authMode:'not_applicable'},mock:{authenticationStatus:'not_applicable',authMode:'not_applicable'}});});
test('workspace layout has one CSS source of truth without global overflow hiding',()=>{const approved=readFileSync(new URL('../../web/src/approved-ui.css',import.meta.url),'utf8');const composition=readFileSync(new URL('../../web/src/composition-final.css',import.meta.url),'utf8');assert.equal((composition.match(/\.workspace-detail-grid\{/g)||[]).length,2);assert.equal((composition.match(/\.workspace-primary\{/g)||[]).length,1);assert.equal((composition.match(/\.workspace-rail\{/g)||[]).length,2);assert.doesNotMatch(approved,/\.workspace-detail-grid\{|\.workspace-primary\{|\.workspace-rail\{/);assert.match(composition,/minmax\(0,380px\)/);assert.match(composition,/@media\(max-width:1279px\)/);assert.doesNotMatch(composition,/body[^}]*overflow-x:hidden/);});
